import React,{useEffect,useState,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowDown,ArrowRight,ArrowUpRight,Blocks,BookOpen,Check,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,Clock,Code2,Copy,Database,FileCode2,FolderTree,GitBranch,Globe,Grid2X2,HelpCircle,History,Layers3,LayoutDashboard,LogOut,MessageCircleQuestion,PanelLeftClose,PanelLeftOpen,Play,Plus,RefreshCw,Search,Settings2,ShieldCheck,SlidersHorizontal,Table2,Terminal,Trash2,Users,X} from 'lucide-react';
import './styles.css';
import {SmartQuery} from './SmartQuery.jsx';
import {SemanticAssets} from './SemanticAssets.jsx';
import {PipelineWorkspace} from './PipelineWorkspace.jsx';
import {ModelPublishing} from './ModelPublishing.jsx';
import {resolveNavigation,navigationHash} from './navigation.js';

let csrf='';
async function api(path,method='GET',body,options={}){
  const response=await fetch('/api'+path,{method,credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...(options.headers||{})},body:body===undefined?undefined:JSON.stringify(body)});
  if(options.rawResponse&&response.ok)return response;
  const data=await response.json();
  if(!response.ok){const d=data.error||data.detail;const error=new Error(typeof d==='string'?d:Array.isArray(d)?d.map(x=>x.msg).join('；'):d?.message||'请求失败');error.status=response.status;error.code=d?.code;error.payload=data;throw error;}
  return data;
}
const menus=[
 {section:'工作空间',items:[['overview','工作台概览',LayoutDashboard]]},
 {section:'数据规划',items:[['domain','业务域',FolderTree],['model','数仓建模',Layers3],['dimension','维度管理',Blocks],['metric','指标管理',Activity]]},
 {section:'数据资产',items:[['semantic','语义资产',BookOpen],['datasource','数据源',Database],['assets','数据地图',Globe],['lineage','数据血缘',GitBranch]]},
 {section:'数据应用',items:[['agent','智能问数',MessageCircleQuestion]]},
 {section:'数据开发',items:[['sql','SQL 工作台',Terminal],['pipelines','数据任务',Code2],['runs','运行中心',Clock],['services','数据服务',Globe],['analyses','保存分析',Activity],['policies','数据授权',Users]]},
 {section:'数据治理',items:[['quality','质量规则',ShieldCheck]]},
 {section:'空间管理',items:[['audit','操作记录',History],['users','成员与权限',Users],['about','开发与依赖',FileCode2]]}
];
const flatMenus=menus.flatMap(g=>g.items);
const labels=Object.fromEntries(flatMenus.map(([k,n])=>[k,n]));
const kindLabels={domain:'业务域',model:'逻辑模型',dimension:'维度',metric:'指标'};
const fmt=d=>d?new Date(d).toLocaleString('zh-CN',{hour12:false}):'—';
const val=v=>v===null||v===undefined?'NULL':typeof v==='object'?JSON.stringify(v):String(v);
const seedFields=[{name:'id',type:'bigint',nullable:false,comment:'主键'}];

function Button({children,icon:Icon,primary=false,danger=false,className='',...props}){return <button className={`btn ${primary?'primary':''} ${danger?'danger':''} ${className}`} {...props}>{Icon&&<Icon size={15}/>}<span>{children}</span></button>;}
function Badge({children,tone='gray'}){return <span className={`badge ${tone}`}>{children}</span>;}
function Empty({icon:Icon=Database,title='暂无数据',detail='创建第一条记录，开始维护工作空间。',action}){return <div className="empty"><div className="empty-icon"><Icon size={29}/></div><h3>{title}</h3><p>{detail}</p>{action}</div>;}
function Modal({title,children,onClose,footer,wide=false}){useEffect(()=>{const fn=e=>{if(e.key==='Escape')onClose();};document.addEventListener('keydown',fn);return()=>document.removeEventListener('keydown',fn);},[onClose]);return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section role="dialog" aria-modal="true" aria-label={title} className={`modal ${wide?'wide':''}`}><header><h2>{title}</h2><button className="icon-btn" aria-label="关闭" onClick={onClose}><X size={19}/></button></header><div className="modal-body">{children}</div>{footer&&<footer>{footer}</footer>}</section></div>;}
function Field({label,required,children,hint}){return <label className="field"><span>{required&&<b>*</b>}{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function DataTable({columns,rows,onRow,empty,compact=false}){return <div className={`table-scroll ${compact?'compact':''}`}><table><thead><tr>{columns.map((c,i)=><th key={i} style={{width:c.width}}>{c.title}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id??i} onClick={()=>onRow?.(r)} className={onRow?'clickable':''}>{columns.map((c,j)=><td key={j}>{c.render?c.render(r,i):val(r[c.key])}</td>)}</tr>)}</tbody></table>{rows.length===0&&(empty||<Empty/>)}</div>;}
function PageHead({eyebrow,title,description,children}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{description}</p></div><div className="head-actions">{children}</div></div>;}

function Login({onLogin}){
 const [username,setUsername]=useState(''),[password,setPassword]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function submit(e){e.preventDefault();setBusy(true);setError('');try{const data=await api('/auth/login','POST',{username,password});csrf=data.csrf;await onLogin();}catch(e){setError(e.message);}finally{setBusy(false);}}
 return <div className="login"><div className="login-story"><a className="brand" href="/"><img src="/mark.svg" alt=""/><span>OntoDataWorks</span><Badge tone="blue">WORKSPACE</Badge></a><div className="story-content"><div className="eyebrow light">让数据，成为可管理的资产</div><h1>从业务定义<br/>到可信数据。</h1><p>连接业务、模型与数据，在一个工作空间中<br/>完成规划、管理和探索。</p><div className="data-visual" aria-hidden="true"><div className="visual-grid"/>{['业务域','数据模型','维度 · 指标','数据资产'].map((x,i)=><div className={`visual-node node-${i}`} key={x}><Database size={21}/><span>{x}</span><i/></div>)}<div className="visual-line l1"/><div className="visual-line l2"/><div className="visual-line l3"/><div className="visual-pill"><CheckCircle2 size={15}/>定义一致 · 来源可查</div></div><div className="story-features"><span><Layers3 size={16}/>统一建模</span><span><GitBranch size={16}/>来源可查</span><span><Terminal size={16}/>查询探索</span></div></div><div className="story-bottom">ONTODATAWORKS <span>本地工作空间</span></div></div><div className="login-panel"><div className="login-top"><Globe size={15}/> 简体中文</div><form onSubmit={submit}><Badge tone="blue">欢迎回来</Badge><h2>登录工作空间</h2><p className="login-sub">连接你的数据，开始今天的工作。</p><Field label="账号" required><input autoComplete="username" value={username} onChange={e=>setUsername(e.target.value)} placeholder="请输入账号" required autoFocus/></Field><Field label="密码" required><input autoComplete="current-password" type="password" value={password} onChange={e=>setPassword(e.target.value)} placeholder="请输入密码" required/></Field>{error&&<div role="alert" className="form-error">{error}</div>}<Button primary disabled={busy} className="login-submit">{busy?'正在登录…':'登录'}<ArrowRight size={16}/></Button><p className="local-hint"><ShieldCheck size={14}/>账号由本地管理员维护</p></form><div className="login-foot">OntoDataWorks · 本体数语 <span>版本 1.1.0</span></div></div></div>;
}

function App(){
 const [session,setSession]=useState(null),[boot,setBoot]=useState(true),[wid,setWid]=useState(Number(new URLSearchParams(location.search).get('workspace'))||Number(localStorage.getItem('wb.workspace'))||1),[route,setRoute]=useState(()=>resolveNavigation(location.hash.slice(1))),[collapsed,setCollapsed]=useState(false),[toast,setToast]=useState(null),[busy,setBusy]=useState(false),[refresh,setRefresh]=useState(0),[confirm,setConfirm]=useState(null),[showHelp,setShowHelp]=useState(false),[globalSearch,setGlobalSearch]=useState('');
 const {page,view}=route;
 const notify=useCallback((text,error=false)=>{setToast({text,error});setTimeout(()=>setToast(null),5500);},[]);
 const loadSession=useCallback(async()=>{const data=await api('/auth/me');csrf=data.csrf;setSession(data);if(!data.workspaces.some(w=>w.id===wid)&&data.workspaces.length)setWid(data.workspaces[0].id);},[wid]);
 useEffect(()=>{loadSession().catch(()=>setSession(null)).finally(()=>setBoot(false));},[]);
 useEffect(()=>{const fn=()=>{const next=resolveNavigation(location.hash.slice(1));const hash=navigationHash(next);if(location.hash.slice(1)!==hash)history.replaceState(null,'','#'+hash);setRoute(next);};fn();window.addEventListener('hashchange',fn);return()=>window.removeEventListener('hashchange',fn);},[]);
 useEffect(()=>{localStorage.setItem('wb.workspace',String(wid));},[wid]);
 const go=(p)=>{const next=resolveNavigation(p);location.hash=navigationHash(next);setRoute(next);};
 const reload=()=>setRefresh(x=>x+1);
 const mutate=async(fn,message)=>{setBusy(true);try{const data=await fn();if(message)notify(message);reload();return data;}catch(e){notify(e.message,true);throw e;}finally{setBusy(false);}};
 const request=useCallback((path,method,body,options)=>api(`/workspaces/${wid}${path}`,method,body,options),[wid]);
 if(boot)return <div className="boot"><img src="/mark.svg" alt=""/><span>正在连接工作空间…</span></div>;
 if(!session)return <Login onLogin={loadSession}/>;
 const ws=session.workspaces.find(w=>w.id===wid);
 const switchWorkspace=(id)=>{const url=new URL(location.href);url.searchParams.set('workspace',String(id));history.replaceState(null,'',url);setWid(id);};
 const common={wid,request,notify,mutate,refresh,busy,go,workspace:ws,workspaces:session.workspaces,switchWorkspace,confirm:(title,action)=>setConfirm({title,action}),role:session.user.role};
 async function createWorkspace(){const name=prompt('工作空间名称');if(!name)return;try{const row=await mutate(()=>api('/workspaces','POST',{name}),'工作空间已创建');await loadSession();setWid(row.id);go('overview');}catch{}}
 async function logout(){try{await api('/auth/logout','POST',{});setSession(null);csrf='';}catch(e){notify(e.message,true);}}
 return <div className={`shell ${collapsed?'collapsed':''}`}><header className="global-bar"><a className="brand" href="#overview"><img src="/mark.svg" alt=""/><span>OntoDataWorks</span></a><div className="global-divider"/><span className="product-label">数据开发与治理</span><div className="space-select"><span>工作空间</span><select aria-label="工作空间" value={wid} onChange={e=>switchWorkspace(Number(e.target.value))}>{session.workspaces.map(w=><option key={w.id} value={w.id}>{w.name}（{w.active_assets||0}）</option>)}</select><Badge tone="green">本地</Badge></div><div className="global-spacer"/><button className="top-help" onClick={()=>setShowHelp(true)}><HelpCircle size={16}/>使用帮助</button><button className="profile" onClick={()=>go('users')}><span className="avatar">{session.user.display_name.slice(0,1)}</span><span>{session.user.display_name}</span><ChevronDown size={12}/></button><button className="icon-btn logout" title="退出登录" aria-label="退出登录" onClick={logout}><LogOut size={16}/></button></header><aside className="sidebar"><div className="side-space"><span className="space-symbol"><Blocks size={19}/></span>{!collapsed&&<div><strong>{ws?.name||'工作空间'}</strong><span>开发环境 / DEVELOPMENT</span></div>}</div><div className="side-search"><Search size={15}/>{!collapsed&&<input placeholder="搜索菜单" value={globalSearch} onChange={e=>setGlobalSearch(e.target.value)}/>}</div><nav>{menus.map(g=><div className="menu-group" key={g.section}>{!collapsed&&<div className="menu-caption">{g.section}</div>}{g.items.filter(([k,n])=>n.includes(globalSearch)&&(k!=='users'||session.user.role==='admin')).map(([k,n,Icon])=><button key={k} title={n} className={`menu-item ${page===k?'active':''}`} onClick={()=>go(k)}><Icon size={17}/>{!collapsed&&<span>{n}</span>}{!collapsed&&page===k&&<i/>}</button>)}</div>)}</nav><div className="sidebar-footer">{!collapsed&&<button onClick={createWorkspace}><Plus size={15}/>新建工作空间</button>}<button onClick={()=>setCollapsed(!collapsed)} aria-label={collapsed?'展开菜单':'折叠菜单'}>{collapsed?<PanelLeftOpen size={17}/>:<PanelLeftClose size={17}/>}</button></div></aside><div className="workspace-content"><div className="context-bar"><div><span>工作空间</span><ChevronRight size={13}/><span>{ws?.name}</span><ChevronRight size={13}/><strong>{labels[page]||'工作台'}</strong>{view&&<><ChevronRight size={13}/><strong>{{publish:'发布建表',history:'发布记录',issues:'异常治理'}[view]}</strong></>}</div><div><span className="status-dot"/>已连接本地服务<button className="icon-btn" aria-label="刷新页面" onClick={reload}><RefreshCw size={14}/></button></div></div><main key={`${wid}:${page}`}>
 {page==='overview'?<Overview {...common} name={session.user.display_name}/>:['domain','dimension','metric','model'].includes(page)?<Documents {...common} kind={page} view={view}/>:page==='datasource'?<Sources {...common}/>:page==='assets'?<Assets {...common}/>:page==='sql'?<SqlWorkbench {...common}/>:page==='lineage'?<Lineage {...common}/>:page==='semantic'?<SemanticAssets key={wid} {...common}/>:page==='agent'?<SmartQuery key={wid} {...common}/>:['pipelines','runs','quality','services','analyses','policies'].includes(page)?<PipelineWorkspace key={`${wid}:${page}`} page={page} view={view} {...common}/>:page==='audit'?<AuditPage {...common}/>:page==='users'?<UsersPage {...common}/>:<About/>}
 </main><footer className="workspace-footer"><span>数据工作台 <span className="faded">/</span> {ws?.name}</span><span>独立实现 · v1.1.0</span></footer></div>{toast&&<div role="status" className={`toast ${toast.error?'error':''}`}>{toast.error?<X size={17}/>:<CheckCircle2 size={17}/>} {toast.text}</div>}{confirm&&<Modal title="确认操作" onClose={()=>setConfirm(null)} footer={<><Button onClick={()=>setConfirm(null)}>取消</Button><Button danger disabled={busy} onClick={async()=>{try{await confirm.action();setConfirm(null);}catch{}}}>确认</Button></>}><p>{confirm.title}</p></Modal>}{showHelp&&<Modal title="工作台使用路径" onClose={()=>setShowHelp(false)}><ol className="help-steps"><li>在「业务域」定义业务边界，在「维度」「指标」中维护一致口径。</li><li>在「数仓建模」明确 ODS / DWD / DWS / DIM / ADS 分层和数据粒度。</li><li>配置 PostgreSQL 数据源，测试连接后采集真实表与字段。</li><li>在「数据地图」搜索元数据，展开抽屉预览前 100 行。</li><li>在「SQL 工作台」执行查询，在「数据血缘」核对成功查询的表级来源与证据。</li></ol></Modal>}</div>;
}

function useData(loader,deps,notify){const [data,setData]=useState(null),[loading,setLoading]=useState(true);useEffect(()=>{let active=true;setLoading(true);loader().then(d=>{if(active)setData(d);}).catch(e=>{if(active)notify(e.message,true);}).finally(()=>{if(active)setLoading(false);});return()=>{active=false;};},deps);return [data,loading,setData];}

function Overview({request,refresh,notify,name,go}){
 const [data,loading]=useData(()=>request('/overview'),[request,refresh],notify);const counts=data?.counts||{};
 return <><PageHead eyebrow="WORKSPACE OVERVIEW" title={`你好，${name}`} description="从业务定义出发，组织数据、建立口径、追溯来源。"><Badge tone="green"><span className="status-dot"/>工作空间运行中</Badge></PageHead><section className="welcome-banner"><div><Badge tone="blue">数据资产全生命周期</Badge><h2>让每一份数据，都有清晰的定义。</h2><p>业务域 → 分层建模 → 元数据采集 → 查询验证 → 来源证据</p><Button primary icon={Plus} onClick={()=>go('domain')}>开始数据规划</Button><button className="text-link" onClick={()=>go('assets')}>探索数据资产 <ArrowRight size={14}/></button></div><div className="banner-map" aria-hidden="true"><div><FolderTree size={23}/><span>业务</span></div><i/><div><Layers3 size={23}/><span>模型</span></div><i/><div><Database size={23}/><span>资产</span></div></div></section><div className="stats-grid">{[['domain','业务域',FolderTree],['model','逻辑模型',Layers3],['metric','指标口径',Activity],['asset','已采集表',Database]].map(([k,n,Icon])=><button className="stat-card" key={k} onClick={()=>go(k==='asset'?'assets':k)}><div><span>{n}</span><Icon size={19}/></div><strong>{loading?'—':counts[k]}</strong><span className="stat-note">工作空间实际维护数量 <ArrowUpRight size={13}/></span></button>)}</div><div className="overview-columns"><section className="panel"><div className="panel-heading"><h2>数仓分层规范</h2><Badge>5 层</Badge></div><p className="panel-sub">用一致的分层，组织从原始记录到应用的数据。</p><div className="layer-list">{data?.layers?.map((l,i)=><div className="layer-row" key={l.code}><span className={`layer-code layer-${i}`}>{l.code}</span><div><strong>{l.name}</strong><p>{l.description}</p></div><ChevronRight size={15}/></div>)}</div></section><section className="panel"><div className="panel-heading"><h2>最近活动</h2><button className="text-link" onClick={()=>go('audit')}>查看全部 <ChevronRight size={13}/></button></div>{data?.activity?.length?<div className="timeline">{data.activity.slice(0,5).map(e=><div key={e.id}><span className="timeline-dot"/><strong>{e.action}</strong><p>{e.actor} · {e.detail}</p><time>{fmt(e.created_at)}</time></div>)}</div>:<Empty icon={Clock} title="工作空间已准备就绪" detail="创建资源或执行采集后，操作记录会显示在这里。"/>}<div className="overview-note"><ShieldCheck size={18}/><p>这里展示实际维护与采集的数据。尚未接入数据源时，不显示演示业务统计。</p></div></section></div></>;
}

function Documents({kind,view='',request,notify,mutate,refresh,busy,confirm,role,go}){
 const [data,loading]=useData(()=>Promise.all([request(`/documents/${kind}`),request('/documents/domain'),request('/documents/dimension'),request('/documents/metric'),request('/assets')]),[kind,request,refresh],notify);
 const [search,setSearch]=useState(''),[layer,setLayer]=useState(''),[editor,setEditor]=useState(null),[history,setHistory]=useState(null),[publishingModel,setPublishingModel]=useState(null);
 const [rows=[],domains=[],dimensions=[],metrics=[],assets=[]]=data||[];
 const filtered=rows.filter(r=>(!layer||r.layer===layer)&&`${r.name} ${r.code}`.toLowerCase().includes(search.toLowerCase()));
 const describe={domain:'按业务过程划分边界，统一模型、维度和指标的归属。',model:'维护模型后，直接预检、发布建表并核对实际结构。',dimension:'维护业务主键与属性，建立跨业务过程的一致维度。',metric:'分开维护原子指标和派生指标；发布口径需引用真实字段。'};
 const blank=()=>({code:'',name:'',description:'',domain_id:null,layer:kind==='model'?'DWD':'',status:'draft',spec:kind==='model'?{grain:'',namespace:'public',fields:seedFields,primary_keys:['id']}:kind==='dimension'?{business_key:'id',attributes:seedFields}:kind==='metric'?{metric_type:'atomic',business_process:'',aggregation:'SUM',measure:'',unit:'',asset_id:null}:{} });
 const domainName=id=>domains.find(d=>d.id===id)?.name||'—';
 function publishModel(row){setPublishingModel(row.id);go('model/publish');}
 const columns=[{title:kindLabels[kind],render:r=><div className="name-cell"><span className="row-icon"><FolderTree size={16}/></span><div><strong>{r.name}</strong><code>{r.code}</code></div></div>},...(kind==='model'?[{title:'数仓分层',render:r=><Badge tone="blue">{r.layer}</Badge>},{title:'数据粒度',render:r=><span className="truncate">{r.spec.grain}</span>}]:kind==='metric'?[{title:'指标类型',render:r=><Badge tone={r.spec.metric_type==='derived'?'purple':'blue'}>{r.spec.metric_type==='derived'?'派生指标':'原子指标'}</Badge>}]:[]),{title:kind==='domain'?'父级业务域':'业务域',render:r=>domainName(r.domain_id)},{title:kind==='model'?'定义状态':'状态',render:r=><Badge tone={r.status==='published'?'green':'gray'}>{r.status==='published'?'已发布':'草稿'}</Badge>},{title:'版本 / 更新时间',render:r=><div className="two-line"><span>v{r.revision}</span><small>{fmt(r.updated_at)}</small></div>},{title:'操作',width:kind==='model'?240:160,render:r=><div className="row-actions"><button onClick={()=>setEditor({...r})}>编辑</button>{kind==='model'&&<button onClick={()=>publishModel(r)}>建表发布</button>}<button onClick={async()=>{try{setHistory(await request(`/documents/${kind}/${r.id}/revisions`));}catch(e){notify(e.message,true);}}}>版本</button><button className="red" onClick={()=>confirm(`删除「${r.name}」？有关联引用时系统会阻止删除。`,()=>mutate(()=>request(`/documents/${kind}/${r.id}`,'DELETE'),'已删除'))}>删除</button></div>}];
 return <>
  <PageHead eyebrow="DATA PLANNING" title={labels[kind]} description={describe[kind]}><Button primary icon={Plus} onClick={()=>setEditor(blank())}>新建{kindLabels[kind]}</Button></PageHead>
  {kind==='model'&&<div className="tabs workspace-tabs" role="tablist" aria-label="数仓建模功能">{[['','模型设计'],['publish','发布建表'],['history','发布记录']].map(([key,title])=><button key={key} role="tab" aria-selected={view===key} className={view===key?'active':''} onClick={()=>go('model'+(key?'/'+key:''))}>{title}</button>)}</div>}
  {kind==='model'&&view?<ModelPublishing models={rows} selectedModel={publishingModel} view={view} request={request} notify={notify} role={role} go={go} onPublished={()=>mutate(async()=>{},null)}/>:<section className="panel list-panel">
   <div className="list-toolbar"><div className="filter-input"><Search size={15}/><input aria-label="搜索名称或编码" placeholder="搜索名称或编码" value={search} onChange={e=>setSearch(e.target.value)}/></div>{kind==='model'&&<select aria-label="数仓分层" value={layer} onChange={e=>setLayer(e.target.value)}><option value="">全部分层</option>{['ODS','DWD','DWS','DIM','ADS'].map(l=><option key={l}>{l}</option>)}</select>}<div className="toolbar-right"><span>{filtered.length} 项</span><Button icon={RefreshCw} onClick={()=>{setSearch('');setLayer('');}}>重置</Button></div></div>
   <DataTable columns={columns} rows={filtered} empty={<Empty icon={kind==='model'?Layers3:FolderTree} title={loading?'正在加载…':`尚未维护${kindLabels[kind]}`} detail={kind==='domain'?'先定义业务域，其他规划资源可关联到这个边界。':`先维护业务域，再创建${kindLabels[kind]}。`} action={<Button primary icon={Plus} onClick={()=>setEditor(blank())}>新建{kindLabels[kind]}</Button>}/>}/><div className="table-footer">共 {filtered.length} 项 <span>按最近更新时间排序</span></div>
  </section>}
  {editor&&<DocumentEditor kind={kind} value={editor} domains={domains} dimensions={dimensions} metrics={metrics} assets={assets} busy={busy} onClose={()=>setEditor(null)} onSave={async(value,publish)=>{const saved=await mutate(()=>request(`/documents/${kind}${editor.id?'/'+editor.id:''}`,editor.id?'PUT':'POST',value),'保存成功');setEditor(null);if(kind==='model'&&publish)publishModel(saved);}}/>}
  {history&&<Modal title="文档版本记录" onClose={()=>setHistory(null)} wide>{history.map(h=><div className="revision" key={h.id}><h3>v{h.revision} <small>{h.actor} · {fmt(h.created_at)}</small></h3><pre>{JSON.stringify(h.snapshot,null,2)}</pre></div>)}</Modal>}
 </>;
}

function DocumentEditor({kind,value,domains,dimensions,metrics,assets,busy,onClose,onSave}){
 const [form,setForm]=useState({...value}),[error,setError]=useState('');const spec=form.spec;const set=(k,v)=>setForm({...form,[k]:v}),setSpec=(k,v)=>set('spec',{...spec,[k]:v});
 const fieldKey=kind==='model'?'fields':'attributes';const fields=spec[fieldKey]||[];
 function updateField(i,k,v){setSpec(fieldKey,fields.map((f,j)=>i===j?{...f,[k]:v}:f));}
 const selectDomain=<select value={form.domain_id||''} onChange={e=>set('domain_id',e.target.value?Number(e.target.value):null)} required={kind!=='domain'}><option value="">{kind==='domain'?'无父级业务域':'请选择业务域'}</option>{domains.filter(d=>d.id!==form.id).map(d=><option key={d.id} value={d.id}>{d.name} / {d.code}</option>)}</select>;
 async function save(e){e.preventDefault();setError('');try{const {id,workspace_id,kind:unused,created_at,updated_at,...payload}=form;await onSave(payload,e.nativeEvent.submitter?.value==='publish');}catch(e){setError(e.message);}}
 return <Modal title={`${value.id?'编辑':'新建'}${kindLabels[kind]}`} onClose={onClose} wide footer={<><Button onClick={onClose}>取消</Button><Button type="submit" form="document-form" disabled={busy}>{busy?'保存中…':'保存'}</Button>{kind==='model'&&<Button primary type="submit" form="document-form" name="intent" value="publish" disabled={busy}>保存并发布建表</Button>}</>}><form id="document-form" onSubmit={save}><div className="form-grid"><Field label="中文名称" required><input value={form.name} onChange={e=>set('name',e.target.value)} required placeholder="例如：交易业务域"/></Field><Field label="英文编码" required><input value={form.code} onChange={e=>set('code',e.target.value)} required placeholder={kind==='model'?'dwd_order_detail':'trade'}/></Field><Field label={kind==='domain'?'父级业务域':'所属业务域'} required={kind!=='domain'}>{selectDomain}</Field><Field label="状态"><select value={form.status} onChange={e=>set('status',e.target.value)}><option value="draft">草稿</option><option value="published">已发布</option></select></Field></div><Field label="业务说明"><textarea rows={2} value={form.description} onChange={e=>set('description',e.target.value)} placeholder="说明边界、口径和维护责任"/></Field>{kind==='model'&&<div className="form-grid"><Field label="数仓分层" required><select value={form.layer} onChange={e=>set('layer',e.target.value)}>{['ODS','DWD','DWS','DIM','ADS'].map(l=><option key={l}>{l}</option>)}</select></Field><Field label="Schema" required><input value={spec.namespace} onChange={e=>setSpec('namespace',e.target.value)} required/></Field><Field label="数据粒度" required><input value={spec.grain} onChange={e=>setSpec('grain',e.target.value)} placeholder="每一行代表什么" required/></Field><Field label="主键（英文逗号分隔）"><input value={(spec.primary_keys||[]).join(',')} onChange={e=>setSpec('primary_keys',e.target.value.split(',').map(s=>s.trim()).filter(Boolean))}/></Field></div>}{kind==='dimension'&&<Field label="业务主键" required><input value={spec.business_key} onChange={e=>setSpec('business_key',e.target.value)} required/></Field>}{['model','dimension'].includes(kind)&&<><div className="sub-heading"><h3>{kind==='model'?'字段定义':'维度属性'}</h3><Button icon={Plus} onClick={()=>setSpec(fieldKey,[...fields,{name:'',type:'text',nullable:true,comment:''}])}>添加字段</Button></div><div className="field-editor"><div className="field-editor-head"><span>英文名称</span><span>数据类型</span><span>中文说明</span><span>可空</span><span/></div>{fields.map((f,i)=><div key={i}><input aria-label={`字段名称${i+1}`} value={f.name} onChange={e=>updateField(i,'name',e.target.value)} required/><select value={f.type||'text'} onChange={e=>updateField(i,'type',e.target.value)}>{['text','varchar(100)','varchar(255)','bigint','integer','double precision','numeric(18,2)','numeric(18,4)','numeric(22,2)','numeric(38,2)','date','timestamp','boolean'].map(t=><option key={t}>{t}</option>)}</select><input aria-label={`字段说明${i+1}`} value={f.comment||''} onChange={e=>updateField(i,'comment',e.target.value)}/><input aria-label={`字段可空${i+1}`} type="checkbox" checked={f.nullable!==false} onChange={e=>updateField(i,'nullable',e.target.checked)}/><button type="button" className="icon-btn" aria-label={`删除字段${i+1}`} onClick={()=>setSpec(fieldKey,fields.filter((_,j)=>j!==i))}><Trash2 size={14}/></button></div>)}</div></>}{kind==='metric'&&<><div className="form-grid"><Field label="指标类型"><select value={spec.metric_type} onChange={e=>setSpec('metric_type',e.target.value)}><option value="atomic">原子指标</option><option value="derived">派生指标</option></select></Field>{spec.metric_type==='derived'?<><Field label="引用原子指标" required><select required value={spec.atomic_metric_id||''} onChange={e=>setSpec('atomic_metric_id',Number(e.target.value))}><option value="">选择原子指标</option>{metrics.filter(m=>m.id!==form.id&&m.spec.metric_type!=='derived').map(m=><option key={m.id} value={m.id}>{m.name}</option>)}</select></Field><Field label="时间窗口" required><input value={spec.time_window||''} onChange={e=>setSpec('time_window',e.target.value)} placeholder="例如：自然日、近 7 日" required/></Field><Field label="业务限定"><input value={spec.qualifier||''} onChange={e=>setSpec('qualifier',e.target.value)} placeholder="例如：已支付订单"/></Field><Field label="统计维度"><select multiple value={(spec.dimension_ids||[]).map(String)} onChange={e=>setSpec('dimension_ids',Array.from(e.target.selectedOptions).map(o=>Number(o.value)))}>{dimensions.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field></>:<><Field label="业务过程" required><input value={spec.business_process||''} onChange={e=>setSpec('business_process',e.target.value)} placeholder="例如：订单支付" required/></Field><Field label="聚合方式"><select value={spec.aggregation||'SUM'} onChange={e=>setSpec('aggregation',e.target.value)}>{['SUM','COUNT','COUNT_DISTINCT','AVG','MIN','MAX'].map(a=><option key={a}>{a}</option>)}</select></Field><Field label="计量单位" required><input value={spec.unit||''} onChange={e=>setSpec('unit',e.target.value)} placeholder="元 / 笔 / 人" required/></Field><Field label="真实来源表"><select value={spec.asset_id||''} onChange={e=>set('spec',{...spec,asset_id:Number(e.target.value)||null,measure:''})}><option value="">草稿可暂不关联</option>{assets.filter(a=>a.state==='active').map(a=><option key={a.id} value={a.id}>{a.name} / {a.table_name}</option>)}</select></Field><Field label="度量字段"><select value={spec.measure||''} onChange={e=>setSpec('measure',e.target.value)}><option value="">选择字段</option>{(assets.find(a=>a.id===spec.asset_id)?.columns||[]).map(c=><option key={c.name} value={c.name}>{c.name}</option>)}</select></Field></>}</div><div className="notice">指标发布校验真实表字段与依赖关系；一期维护指标定义，尚未提供任意派生表达式的自动计算引擎。</div></>}{error&&<div role="alert" className="form-error">{error}</div>}</form></Modal>;
}

function Sources({request,notify,mutate,refresh,busy}){
 const [rows,loading]=useData(()=>request('/datasources'),[request,refresh],notify),[editor,setEditor]=useState(null),[error,setError]=useState('');
 const blank={name:'',host:'',port:5432,database:'',username:'',password:'',schemas:['public']};
 async function action(id,type){try{const r=await mutate(()=>request(`/datasources/${id}/${type}`,'POST',{}));notify(type==='test'?'连接测试通过':`采集完成：${r.tables} 张表，${r.columns} 个字段`);}catch{}}
 return <><PageHead eyebrow="DATA CONNECTION" title="数据源" description="连接独立数据库，按需采集真实元数据。当前支持 PostgreSQL。"><Button primary icon={Plus} onClick={()=>{setEditor(blank);setError('');}}>新建数据源</Button></PageHead><div className="notice"><ShieldCheck size={16}/>连接密码加密保存，接口不返回密码。查询台使用只读事务；建议配置专用只读账号，建表另配受控账号。</div><div className="source-grid">{rows?.map(s=><section className="source-card panel" key={s.id}><div className="source-card-head"><div className="source-logo"><Database size={25}/></div><div><h3>{s.name}</h3><span>PostgreSQL</span></div><Badge tone={s.last_tested_at?'green':'gray'}>{s.last_tested_at?'已验证':'待测试'}</Badge></div><dl><dt>主机</dt><dd>{s.host}:{s.port}</dd><dt>数据库</dt><dd>{s.database}</dd><dt>Schema</dt><dd>{s.schemas.join(', ')}</dd><dt>最近采集</dt><dd>{fmt(s.last_collected_at)}</dd></dl><footer><Button icon={SlidersHorizontal} onClick={()=>{setEditor({...s,password:''});setError('');}}>配置</Button><Button disabled={busy} onClick={()=>action(s.id,'test')}>测试连接</Button><Button primary disabled={busy} icon={RefreshCw} onClick={()=>action(s.id,'collect')}>采集元数据</Button></footer></section>)}</div>{!rows?.length&&<section className="panel"><Empty title={loading?'正在加载…':'连接第一个数据源'} detail="连接后可采集表、字段、注释和结构指纹，再进入数据地图预览。" action={<Button primary icon={Plus} onClick={()=>setEditor(blank)}>新建数据源</Button>}/></section>}{editor&&<Modal title={editor.id?'配置数据源':'新建 PostgreSQL 数据源'} onClose={()=>setEditor(null)} footer={<><Button onClick={()=>setEditor(null)}>取消</Button><Button primary disabled={busy} onClick={()=>document.getElementById('source-form').requestSubmit()}>保存</Button></>}><form id="source-form" onSubmit={async e=>{e.preventDefault();try{const payload=Object.fromEntries(Object.keys(blank).map(k=>[k,editor[k]]));await mutate(()=>request('/datasources'+(editor.id?'/'+editor.id:''),editor.id?'PUT':'POST',payload),'数据源已保存');setEditor(null);}catch(e){setError(e.message);}}}><Field label="连接名称" required><input value={editor.name} onChange={e=>setEditor({...editor,name:e.target.value})} required/></Field><div className="form-grid">{[['host','主机地址'],['port','端口'],['database','数据库'],['username','用户名']].map(([k,n])=><Field key={k} label={n} required><input value={editor[k]} type={k==='port'?'number':'text'} onChange={e=>setEditor({...editor,[k]:k==='port'?Number(e.target.value):e.target.value})} required/></Field>)}</div><Field label="密码" required={!editor.id} hint={editor.id?'留空表示保留原密码':''}><input autoComplete="new-password" type="password" value={editor.password} onChange={e=>setEditor({...editor,password:e.target.value})} required={!editor.id}/></Field><Field label="采集 Schema（逗号分隔）" required><input value={editor.schemas.join(',')} onChange={e=>setEditor({...editor,schemas:e.target.value.split(',').map(s=>s.trim())})}/></Field>{error&&<div className="form-error">{error}</div>}</form></Modal>}</>;
}

function Assets({request,notify,refresh,mutate,workspace,workspaces=[],switchWorkspace,role}){
 const [data,loading]=useData(()=>Promise.all([request('/assets'),request('/documents/domain')]),[request,refresh],notify);
 const [rows=[],domains=[]]=data||[];
 const [search,setSearch]=useState(''),[layer,setLayer]=useState(''),[domain,setDomain]=useState(''),[selectedId,setSelectedId]=useState(null),[tab,setTab]=useState('fields'),[preview,setPreview]=useState(null),[previewBusy,setPreviewBusy]=useState(false),[editor,setEditor]=useState(false),[history,setHistory]=useState(null),[business,setBusiness]=useState(null);
 const selected=rows.find(a=>a.id===selectedId);
 const filtered=rows.filter(a=>`${a.name} ${a.table_name} ${a.namespace} ${a.columns.map(c=>c.name+' '+c.comment+' '+(c.business_metadata?.chinese_name||'')).join(' ')}`.toLowerCase().includes(search.toLowerCase())&&(!layer||a.layer===layer)&&(!domain||a.domain_id===Number(domain)));
 const valid=rows.filter(a=>a.state==='active'),maintained=valid.filter(a=>a.metadata_state==='complete');
 const other=workspaces.filter(w=>w.id!==workspace?.id&&w.active_assets>rows.length);
 const open=a=>{setSelectedId(a.id);setTab('fields');setPreview(null);setBusiness({name:a.name,description:a.description,domain_id:a.domain_id});};
 async function loadPreview(){setTab('preview');setPreviewBusy(true);try{setPreview(await request(`/assets/${selected.id}/preview`));}catch(e){notify(e.message,true);}finally{setPreviewBusy(false);}}
 const classification={public:'公开',internal:'内部',sensitive:'敏感'};
 const roles={identifier:'标识',attribute:'属性',measure:'度量',event_time:'业务时间',status:'状态'};
 return <><PageHead eyebrow="DATA CATALOG" title="数据地图" description={`当前空间：${workspace?.name||'—'}。查看中文元数据、物理结构与实时数据。`}><Badge tone="blue">{valid.length} 张有效表</Badge></PageHead>
 {other.length>0&&<div className="notice workspace-notice"><FolderTree size={17}/><span>当前「{workspace?.name}」有 {valid.length} 条有效连接资产。电商等业务数据维护在独立工作空间。</span>{other.map(w=><Button key={w.id} primary onClick={()=>switchWorkspace(w.id)}>切换到{w.name}（{w.active_assets} 张）</Button>)}</div>}
 <div className="metadata-summary"><span>工作空间 <strong>{workspace?.name}</strong></span><span>中文元数据齐全 <strong>{maintained.length} / {valid.length} 表</strong></span><span>字段 <strong>{valid.reduce((n,a)=>n+a.maintained_columns,0)} / {valid.reduce((n,a)=>n+a.columns.length,0)}</strong></span><span>物理结构与业务释义独立维护</span></div>
 <section className="panel list-panel"><div className="list-toolbar"><div className="filter-input wide"><Search size={16}/><input aria-label="搜索数据资产" value={search} onChange={e=>setSearch(e.target.value)} placeholder="搜索中文表名、字段中文名或物理名称"/></div><select value={layer} onChange={e=>setLayer(e.target.value)} aria-label="分层筛选"><option value="">全部分层</option>{['ODS','DWD','DWS','DIM','ADS'].map(l=><option key={l}>{l}</option>)}</select><select aria-label="业务域筛选" value={domain} onChange={e=>setDomain(e.target.value)}><option value="">全部业务域</option>{domains.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select><span className="toolbar-right">筛选后 {filtered.length} 张表</span></div>
 <DataTable rows={filtered} onRow={open} columns={[{title:'中文表名 / 物理名称',render:r=><div className="name-cell"><span className="row-icon"><Table2 size={17}/></span><div><strong>{r.name}</strong><code>{r.namespace}.{r.table_name}</code></div></div>},{title:'分层',render:r=><Badge tone="blue">{r.layer||'待分类'}</Badge>},{title:'业务域',render:r=>domains.find(d=>d.id===r.domain_id)?.name||'待维护'},{title:'字段',render:r=>r.columns.length},{title:'中文元数据',render:r=><div className="two-line"><Badge tone={r.metadata_state==='complete'?'green':'orange'}>{r.metadata_state==='complete'?'齐全':'待维护'}</Badge><small>{r.maintained_columns}/{r.columns.length} 字段</small></div>},{title:'责任人',render:r=>r.governance?.spec.owner||'待维护'},{title:'物理状态',render:r=><Badge tone={r.state==='active'?'green':'orange'}>{r.state==='active'?'有效':r.state==='missing'?'表缺失':'需采集'}</Badge>},{title:'',render:()=> <ChevronRight size={16}/>}]} empty={<Empty icon={Globe} title={loading?'正在加载…':'本空间暂无匹配资产'} detail="检查工作空间和筛选条件，或在数据源中采集。"/>}/></section>
 {selected&&<div className="drawer-overlay" onMouseDown={e=>{if(e.target===e.currentTarget)setSelectedId(null);}}><aside className="drawer metadata-drawer" role="dialog" aria-modal="true" aria-label="数据表详情"><header><div><Badge tone="blue">{selected.layer||'TABLE'}</Badge><h2>{selected.name}</h2><code>{selected.namespace}.{selected.table_name}</code></div><button className="icon-btn" aria-label="关闭抽屉" onClick={()=>setSelectedId(null)}><X size={20}/></button></header><div className="drawer-info"><span>{selected.columns.length} 个字段</span><span>{domains.find(d=>d.id===selected.domain_id)?.name||'业务域待维护'}</span><span>元数据版本 {selected.governance?'v'+selected.governance.revision:'未维护'}</span></div>
 <div className="tabs"><button className={tab==='fields'?'active':''} onClick={()=>setTab('fields')}>字段与中文释义</button><button className={tab==='preview'?'active':''} onClick={loadPreview}>数据预览 · 100 行</button><button className={tab==='business'?'active':''} onClick={()=>setTab('business')}>表级元数据</button></div><div className="drawer-content">
 {tab==='fields'?<><div className="metadata-actions"><span>类型与主外键来自真实数据库；中文业务定义可独立维护。</span>{role!=='viewer'&&<Button primary icon={SlidersHorizontal} onClick={()=>setEditor(true)}>维护中文元数据</Button>}</div><DataTable rows={selected.columns} columns={[{title:'中文字段名 / 英文名称',render:r=><div className="two-line"><strong>{r.business_metadata?.chinese_name||'待维护中文名'}</strong><code>{r.name}</code></div>},{title:'业务释义',render:r=><div className="field-definition">{r.business_metadata?.definition||r.comment||'待维护'}{r.business_metadata?.unit&&<small>单位：{r.business_metadata.unit}</small>}</div>},{title:'数据类型 / 可空',render:r=><div className="two-line"><code>{r.type}</code><small>{r.nullable?'允许空值':'非空'}</small></div>},{title:'主外键',render:r=><div>{r.primary_key&&<Badge tone="blue">PK</Badge>}{(r.foreign_keys||[]).map(f=><small className="key-reference" key={f.constraint}>FK → {f.namespace}.{f.table}.{f.column}</small>)}</div>},{title:'角色 / 分级',render:r=><div className="two-line"><span>{roles[r.business_metadata?.semantic_role]||'待维护'}</span><small>{classification[r.business_metadata?.classification]||'待分级'}</small></div>} ]}/></>:tab==='preview'?previewBusy?<Empty title="正在查询实时数据…"/>:preview?<><div className="notice">实时数据库查询 · {preview.rows.length} 行 · {preview.order_by?.length?`按主键 ${preview.order_by.join(', ')} 排序`:'未定义主键，未排序'}</div><DataTable columns={preview.columns.map((c,i)=>({title:<div className="two-line"><strong>{selected.columns.find(f=>f.name===c)?.business_metadata?.chinese_name||c}</strong><small>{c}</small></div>,render:r=>val(r[i])}))} rows={preview.rows}/></>:null:<>
 <div className="metadata-actions"><Badge tone={selected.metadata_state==='complete'?'green':'orange'}>{selected.metadata_state==='complete'?'中文元数据齐全':'元数据待维护'}</Badge>{role!=='viewer'&&<Button primary onClick={()=>setEditor(true)}>维护中文元数据</Button>}<Button onClick={async()=>{try{setHistory(await request(`/assets/${selected.id}/metadata/revisions`));}catch(e){notify(e.message,true);}}}>维护版本</Button></div>
 <dl className="catalog-definition"><dt>责任人 / 团队</dt><dd>{selected.governance?.spec.owner||'待维护'}</dd><dt>数据粒度</dt><dd>{selected.governance?.spec.grain||'待维护'}</dd><dt>更新策略</dt><dd>{selected.governance?.spec.update_policy||'待维护'}</dd><dt>质量与使用限制</dt><dd>{selected.governance?.spec.quality_note||'待维护'}</dd><dt>维护时间 / 人</dt><dd>{selected.governance?fmt(selected.governance.updated_at)+' / '+selected.governance.actor:'未维护'}</dd></dl>
 <Field label="中文表名"><input value={business?.name||''} onChange={e=>setBusiness({...business,name:e.target.value})} disabled={role==='viewer'}/></Field><Field label="所属业务域"><select value={business?.domain_id||''} onChange={e=>setBusiness({...business,domain_id:Number(e.target.value)||null})} disabled={role==='viewer'}><option value="">待维护</option>{domains.map(d=><option key={d.id} value={d.id}>{d.name}</option>)}</select></Field><Field label="表业务说明"><textarea value={business?.description||''} onChange={e=>setBusiness({...business,description:e.target.value})} disabled={role==='viewer'}/></Field>{role!=='viewer'&&<Button onClick={async()=>{try{await mutate(()=>request(`/assets/${selected.id}`,'PATCH',business),'表业务信息已保存');}catch{}}}>保存表业务信息</Button>}<div className="fingerprint"><span>物理结构指纹 SHA-256</span><code>{selected.fingerprint}</code><small>中文定义重新采集后保留；不会改变物理字段指纹。</small></div></>}
 </div></aside></div>}
 {editor&&selected&&<CatalogMetadataEditor asset={selected} onClose={()=>setEditor(false)} onSave={async payload=>{await mutate(()=>request(`/assets/${selected.id}/metadata`,'PUT',payload),'中文元数据已保存并记录版本');setEditor(false);}}/>}
 {history&&<Modal title="中文元数据版本" onClose={()=>setHistory(null)} wide>{history.length?history.map(h=><div className="revision" key={h.id}><h3>v{h.revision} · {h.actor} · {fmt(h.created_at)}</h3><pre className="code-block">{JSON.stringify(h.spec,null,2)}</pre></div>):<Empty title="暂无维护版本"/>}</Modal>}
 </>;
}

function CatalogMetadataEditor({asset,onClose,onSave}){
 const old=asset.governance;const [form,setForm]=useState(old?{...old.spec,columns:old.spec.columns.map(c=>({...c})),revision:old.revision}:{revision:0,owner:'',grain:'',update_policy:'',quality_note:'',certification:'unreviewed',columns:asset.columns.map(c=>({name:c.name,chinese_name:'',definition:c.comment||'',semantic_role:c.primary_key||c.foreign_keys?.length?'identifier':c.type.includes('timestamp')||c.type==='date'?'event_time':'attribute',classification:'internal',unit:'',quality_rules:[],enum_values:[]}))}),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const change=(k,v)=>setForm({...form,[k]:v});const field=(i,k,v)=>change('columns',form.columns.map((c,j)=>i===j?{...c,[k]:v}:c));
 return <Modal title={`维护中文元数据 · ${asset.name}`} wide onClose={onClose} footer={<><span className="muted">{form.columns.length} 个字段 · 当前 v{form.revision}</span><Button onClick={onClose}>取消</Button><Button primary disabled={busy} onClick={()=>document.getElementById('catalog-metadata-form').requestSubmit()}>{busy?'保存中…':'保存元数据'}</Button></>}><form id="catalog-metadata-form" onSubmit={async e=>{e.preventDefault();setBusy(true);setError('');try{await onSave(form);}catch(e){setError(e.message);}finally{setBusy(false);}}}>
 <div className="form-grid"><Field label="责任人 / 团队" required><input required value={form.owner} onChange={e=>change('owner',e.target.value)}/></Field><Field label="数据粒度" required><input required value={form.grain} onChange={e=>change('grain',e.target.value)} placeholder="一行表示一个订单，唯一键为订单编号"/></Field></div><Field label="更新策略" required><input required value={form.update_policy} onChange={e=>change('update_policy',e.target.value)}/></Field><Field label="质量说明与适用范围" required><textarea required value={form.quality_note} onChange={e=>change('quality_note',e.target.value)}/></Field>
 <div className="notice">编辑中文定义会保存新版本。物理类型、主外键仍以数据库采集结果为准；规则说明不代表已经执行质量检测。</div>
 <div className="metadata-field-list">{form.columns.map((c,i)=><section className="metadata-field-card" key={c.name}><div className="metadata-field-heading"><code>{c.name}</code><small>{asset.columns.find(f=>f.name===c.name)?.type}</small></div><div className="form-grid"><Field label="中文字段名" required><input aria-label={`中文字段名 ${c.name}`} required value={c.chinese_name} onChange={e=>field(i,'chinese_name',e.target.value)}/></Field><Field label="语义角色"><select value={c.semantic_role} onChange={e=>field(i,'semantic_role',e.target.value)}>{Object.entries({identifier:'标识',attribute:'属性',measure:'度量',event_time:'业务时间',status:'状态'}).map(([v,n])=><option key={v} value={v}>{n}</option>)}</select></Field></div><Field label="业务释义" required><textarea aria-label={`业务释义 ${c.name}`} required value={c.definition} onChange={e=>field(i,'definition',e.target.value)}/></Field><div className="form-grid"><Field label="数据分级"><select value={c.classification} onChange={e=>field(i,'classification',e.target.value)}><option value="public">公开</option><option value="internal">内部</option><option value="sensitive">敏感</option></select></Field><Field label="计量单位"><input value={c.unit} onChange={e=>field(i,'unit',e.target.value)}/></Field></div><Field label="质量规则说明（每行一条）"><textarea value={c.quality_rules.join('\n')} onChange={e=>field(i,'quality_rules',e.target.value.split('\n').filter(Boolean))}/></Field>{c.enum_values.length>0&&<p className="enum-values">当前模拟数据枚举：{c.enum_values.join('、')}</p>}</section>)}</div>{error&&<div className="form-error" role="alert">{error}</div>}</form></Modal>;
}

function SqlWorkbench({request,notify,refresh}){
 const [data,,setData]=useData(()=>Promise.all([request('/datasources'),request('/queries'),request('/assets')]),[request,refresh],notify);const [sources=[],history=[],assets=[]]=data||[];
 const [sid,setSid]=useState(''),[query,setQuery]=useState('SELECT current_date AS today;'),[result,setResult]=useState(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[tab,setTab]=useState('result');
 const sourceId=Number(sid)||sources[0]?.id;
 async function run(){setBusy(true);setError('');setTab('result');try{const r=await request('/queries','POST',{datasource_id:sourceId,sql:query});setResult(r);const h=await request('/queries');setData([sources,h,assets]);notify(`执行成功 · ${r.row_count} 行 · ${r.duration_ms} ms`);}catch(e){setResult(null);setError(e.message);}finally{setBusy(false);}}
 return <><PageHead eyebrow="SQL WORKSPACE" title="SQL 工作台" description="在只读事务中探索真实数据。成功查询自动留下表级来源证据。"/><section className="sql-layout"><aside className="sql-explorer"><div className="panel-heading"><h3>数据资源</h3><Database size={16}/></div><select aria-label="查询数据源" value={sourceId||''} onChange={e=>setSid(e.target.value)}><option value="">选择数据源</option>{sources.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select><div className="explorer-label">已采集物理表</div>{assets.filter(a=>a.datasource_id===sourceId&&a.state==='active').map(a=><button className="explorer-table" key={a.id} title="插入查询" onClick={()=>setQuery(`SELECT *\nFROM "${a.namespace}"."${a.table_name}"\nLIMIT 100;`)}><Table2 size={15}/><span>{a.name}<small className="key-reference">{a.namespace}.{a.table_name}</small></span></button>)}{!assets.some(a=>a.datasource_id===sourceId)&&<p className="muted small-pad">暂无已采集表</p>}<div className="sql-rules"><ShieldCheck size={17}/><strong>查询保护</strong><p>单条 SELECT / WITH<br/>最多返回 1,000 行<br/>10 秒超时 · 只读事务</p></div></aside><div className="sql-main"><div className="sql-editor-bar"><span><FileCode2 size={15}/>未命名查询.sql</span><Badge>PostgreSQL</Badge></div><div className="sql-editor"><div className="line-numbers">{query.split('\n').map((_,i)=><div key={i}>{i+1}</div>)}</div><textarea spellCheck="false" aria-label="SQL 编辑器" value={query} onChange={e=>setQuery(e.target.value)} onKeyDown={e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();if(sourceId&&!busy)run();}}}/></div><div className="sql-actions"><Button primary icon={Play} disabled={busy||!sourceId} onClick={run}>{busy?'执行中…':'运行 SQL'}</Button><span>Ctrl + Enter</span><span className="sql-readonly"><ShieldCheck size={13}/>只读查询</span></div><div className="result-tabs tabs"><button className={tab==='result'?'active':''} onClick={()=>setTab('result')}>查询结果 {result&&`(${result.row_count})`}</button><button className={tab==='history'?'active':''} onClick={()=>setTab('history')}>执行历史 ({history.length})</button></div>{tab==='result'?error?<div className="query-error"><h3>执行未完成</h3><p>{error}</p></div>:result?<><div className="result-meta"><span><CheckCircle2 size={14}/>执行成功</span><span>{result.duration_ms} ms</span><span>{result.row_count} 行{result.truncated?'（已截断）':''}</span><span>{result.verified_sources} 个已验证来源</span></div><DataTable compact columns={result.columns.map((c,i)=>({title:c,render:r=>val(r[i])}))} rows={result.rows}/></>:<Empty icon={Terminal} title="准备好探索数据了吗" detail="选择数据源并运行查询，结果将在这里显示。"/>:<DataTable compact rows={history} onRow={r=>{setQuery(r.sql);setSid(String(r.datasource_id));setTab('result');}} columns={[{title:'查询',render:r=><code className="truncate">{r.sql}</code>},{title:'状态',render:r=><Badge tone={r.status==='success'?'green':'orange'}>{r.status==='success'?'成功':'失败'}</Badge>},{title:'行数',key:'row_count'},{title:'耗时',render:r=>r.duration_ms+' ms'},{title:'执行时间',render:r=>fmt(r.created_at)}]}/>}</div></section></>;
}

function Lineage({request,notify,refresh}){
 const [runs,loading]=useData(()=>request('/transforms'),[request,refresh],notify);
 const [mode,setMode]=useState('warehouse_transform'),[search,setSearch]=useState(''),[selected,setSelected]=useState(null);
 const active=(runs||[]).filter(r=>r.kind===mode&&`${r.target} ${r.target_name} ${r.inputs.map(i=>i.source+' '+i.name).join(' ')}`.toLowerCase().includes(search.toLowerCase()));
 const total=kind=>(runs||[]).filter(r=>r.kind===kind).reduce((n,r)=>n+r.inputs.length,0);
 return <><PageHead eyebrow="DATA LINEAGE" title="数据血缘" description="按真实 SQL 追溯表间加工，并区分当前重算证据、模拟生成声明和查询来源。"/><div className="tabs"><button className={mode==='warehouse_transform'?'active':''} onClick={()=>setMode('warehouse_transform')}>数仓加工 · {total('warehouse_transform')} 条</button><button className={mode==='synthetic_generation'?'active':''} onClick={()=>setMode('synthetic_generation')}>模拟源生成 · {total('synthetic_generation')} 条</button><button className={mode==='query'?'active':''} onClick={()=>setMode('query')}>查询来源</button></div>{mode==='query'?<QueryLineage request={request} notify={notify} refresh={refresh}/>:<><div className="notice"><GitBranch size={16}/>{mode==='warehouse_transform'?'来自本次 PostgreSQL 实际重建；API 再次执行加工 SELECT，按物理主键逐行逐字段核对目标。浮点绝对容差 1e-7。':'这些是原合成数据生成器的静态 SQL 依赖；本次 ODS 导入既有快照，没有重新执行生成器，不代表历史运行证据。'}</div><section className="panel list-panel"><div className="list-toolbar"><div className="filter-input wide"><Search size={16}/><input aria-label="搜索血缘" placeholder="搜索上游、下游或中文表名" value={search} onChange={e=>setSearch(e.target.value)}/></div><span className="toolbar-right">{active.length} 个下游 · {active.reduce((n,r)=>n+r.inputs.length,0)} 条依赖</span></div><DataTable rows={active} onRow={setSelected} columns={[{title:'上游表',render:r=><div className="two-line">{r.inputs.map(i=><div key={i.asset_id}><strong>{i.name}</strong><code>{i.source}</code></div>)}</div>},{title:'下游表',render:r=><div className="two-line"><strong>{r.target_name}</strong><code>{r.target}</code></div>},{title:'验证状态',render:r=><Badge tone={r.status==='recomputed_match'?'green':'orange'}>{r.status==='recomputed_match'?'重算一致':'仅生成声明'}</Badge>},{title:'目标行数',render:r=>r.evidence.target_count?.toLocaleString()||'—'},{title:'核对时间',render:r=>fmt(r.evidence.verified_at)},{title:'',render:()=> <ChevronRight size={16}/>}]} empty={<Empty title={loading?'正在加载…':'暂无加工证据'} detail="运行迁移脚本后可在这里核对真实依赖。"/>}/></section></>}{selected&&<Modal wide title="表间加工证据" onClose={()=>setSelected(null)}><div className="evidence-summary"><Badge tone={selected.status==='recomputed_match'?'green':'orange'}>{selected.status==='recomputed_match'?'重算一致':'声明关系'}</Badge><strong>{selected.target_name} / {selected.target}</strong></div><div className="lineage-graph"><div className="source-nodes">{selected.inputs.map(i=><div className="lineage-node" key={i.asset_id}><Table2 size={17}/><div><strong>{i.name}</strong><small>{i.source}</small></div></div>)}</div><div className="graph-connector"><ArrowRight size={22}/></div><div className="lineage-node result-node"><Table2 size={18}/><div><strong>{selected.target_name}</strong><small>{selected.target}</small></div></div></div><h3>加工 SQL</h3><pre className="code-block">{selected.select_sql}</pre><h3>核对与构建证据</h3><pre className="code-block">{JSON.stringify(selected.evidence,null,2)}</pre></Modal>}</>;
}

function QueryLineage({request,notify,refresh}){
 const [edges,loading]=useData(()=>request('/lineage'),[request,refresh],notify);const [selected,setSelected]=useState(null);
 const groups=Object.values((edges||[]).reduce((acc,e)=>{(acc[e.query_id]??={id:e.query_id,edges:[]}).edges.push(e);return acc;},{})).reverse();
 return <><PageHead eyebrow="DATA LINEAGE" title="数据血缘" description="只展示成功执行 SQL 后验证过的表级来源，点击关系可检查证据。"><Badge tone="green">实际执行证据</Badge></PageHead><div className="notice"><GitBranch size={16}/>当前页展示物理表 → 查询结果的来源关系；表间加工请切换「数仓加工」，本期均为表级血缘。</div>{groups.length?groups.map(g=><section className="panel lineage-panel" key={g.id}><div className="panel-heading"><h3>查询结果 #{g.id}</h3><span>{fmt(g.edges[0].created_at)}</span></div><div className="lineage-graph"><div className="source-nodes">{g.edges.map(e=><button className="lineage-node" key={e.id} onClick={()=>setSelected(e)}><span className="row-icon"><Table2 size={18}/></span><div><small>已验证物理表</small><strong>{e.source}</strong></div><CheckCircle2 size={15}/></button>)}</div><div className="graph-connector"><span/><ArrowRight size={21}/><small>SQL 执行验证</small></div><button className="lineage-node result-node" onClick={()=>setSelected(g.edges[0])}><Terminal size={20}/><div><small>查询结果</small><strong>query:{g.id}</strong></div></button></div></section>):<section className="panel"><Empty icon={GitBranch} title={loading?'正在加载…':'等待第一条来源证据'} detail="采集物理表后，在 SQL 工作台成功执行引用该表的查询，即可形成真实表级来源。"/></section>}{selected&&<Modal title="血缘证据" onClose={()=>setSelected(null)} wide><div className="evidence-summary"><Badge tone="green">成功执行</Badge><strong>{selected.source} → {selected.target}</strong></div><dl className="evidence-list"><dt>证据编号</dt><dd>lineage:{selected.id}</dd><dt>查询编号</dt><dd>query:{selected.query_id}</dd><dt>采集时间</dt><dd>{fmt(selected.evidence.metadata_collected_at)}</dd><dt>执行前结构核对</dt><dd>{fmt(selected.evidence.physical_schema_verified_at)}</dd><dt>SQL SHA-256</dt><dd><code>{selected.evidence.sql_sha256}</code></dd><dt>元数据结构指纹</dt><dd><code>{selected.evidence.metadata_fingerprint}</code></dd><dt>证据范围</dt><dd>表级来源到查询结果，来自实际成功执行；不等同于字段血缘。</dd></dl></Modal>}</>;
}

function AuditPage({request,notify,refresh}){const [rows]=useData(()=>request('/audit'),[request,refresh],notify);return <><PageHead eyebrow="WORKSPACE ADMINISTRATION" title="操作记录" description="本地记录建模、采集和查询操作，不发送到外部监测平台。"/><section className="panel"><DataTable rows={rows||[]} columns={[{title:'操作',render:r=><Badge tone="blue">{r.action}</Badge>},{title:'操作人',key:'actor'},{title:'说明',key:'detail'},{title:'时间',render:r=>fmt(r.created_at)}]}/></section></>;}

function UsersPage({notify,mutate,refresh,wid}){
 const [rows]=useData(()=>api('/users'),[refresh],notify),[form,setForm]=useState(null),[error,setError]=useState('');
 return <><PageHead eyebrow="ACCESS MANAGEMENT" title="成员与权限" description="管理员维护用户；开发者可维护资源，只读成员可查询和浏览。"><Button primary icon={Plus} onClick={()=>{setForm({username:'',display_name:'',password:'',role:'developer',workspace_ids:[wid]});setError('');}}>添加成员</Button></PageHead><section className="panel"><DataTable rows={rows||[]} columns={[{title:'成员',render:r=><div className="name-cell"><span className="avatar">{r.display_name.slice(0,1)}</span><div><strong>{r.display_name}</strong><code>{r.username}</code></div></div>},{title:'角色',render:r=><Badge tone="blue">{{admin:'管理员',developer:'开发者',viewer:'只读成员'}[r.role]}</Badge>},{title:'状态',render:r=><Badge tone="green">{r.enabled?'可用':'停用'}</Badge>}]}/></section>{form&&<Modal title="添加工作空间成员" onClose={()=>setForm(null)} footer={<><Button onClick={()=>setForm(null)}>取消</Button><Button primary onClick={()=>document.getElementById('user-form').requestSubmit()}>创建成员</Button></>}><form id="user-form" onSubmit={async e=>{e.preventDefault();try{await mutate(()=>api('/users','POST',form),'成员已创建');setForm(null);}catch(e){setError(e.message);}}}>{[['username','账号'],['display_name','显示名称'],['password','初始密码']].map(([k,n])=><Field key={k} label={n} required><input autoComplete={k==='password'?'new-password':'off'} type={k==='password'?'password':'text'} minLength={k==='password'?12:1} required value={form[k]} onChange={e=>setForm({...form,[k]:e.target.value})}/></Field>)}<Field label="角色"><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="developer">开发者</option><option value="viewer">只读成员</option><option value="admin">管理员</option></select></Field><div className="notice">非管理员成员将被加入当前工作空间；管理员可管理所有工作空间。</div>{error&&<div className="form-error">{error}</div>}</form></Modal>}</>;
}

function About(){return <><PageHead eyebrow="INDEPENDENT IMPLEMENTATION" title="开发与依赖" description="新的业务代码与数据结构独立维护，版本与技术边界清晰可查。"/><div className="about-grid"><section className="panel"><div className="panel-heading"><h2>独立数据工作台</h2><Badge tone="blue">v1.1.0</Badge></div><p>前端和业务 API 从空项目编写，使用独立账号、数据库、容器和源码目录。未复用 qData 的组件、接口实现、SQL 初始化脚本、标识和图片。</p><dl><dt>前端</dt><dd>React · Vite · Lucide</dd><dt>后端</dt><dd>FastAPI · SQLAlchemy · psycopg</dd><dt>数据存储</dt><dd>PostgreSQL 16</dd><dt>查询解析</dt><dd>SQLGlot</dd></dl></section><section className="panel"><h2>一期能力边界</h2><ul className="about-list"><li>业务域、维度、逻辑模型与指标文档版本维护</li><li>PostgreSQL 连接、元数据采集和实时预览</li><li>SQL 只读查询和真实执行的表级来源证据</li><li>v1.1 新增数据同步、SQL 加工、质量门禁、运行中心与参数化数据服务；节点验收范围见交付清单</li></ul><div className="notice">通用开源依赖保留各自许可。独立实现不表示这些第三方依赖没有许可要求。</div></section></div></>;}

createRoot(document.getElementById('root')).render(<App/>);
